from datetime import datetime,timedelta
def field_match(field,value):
    for part in field.split(','):
        if part=='*':return True
        if part.startswith('*/'):
            if value % int(part[2:])==0:return True
        elif '-' in part:
            lo,hi=map(int,part.split('-'))
            if lo<=value<=hi:return True
        elif value==int(part):return True
    return False
def cron_match(expr,dt):
    vals=[dt.minute,dt.hour,dt.day,dt.month,dt.isoweekday()%7]
    return all(field_match(f,v) for f,v in zip(expr.split(),vals))
